		/** 
		 * Tests creating a new Loan.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Loan");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Loan" );

			try {            
				Loan entity = LoanService.getLoanInstance().createLoan( generateNewEntity() );
				thePrimaryKey = entity.getLoanId();
				LOGGER.info( "-- Successfully created a Loan with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Loan. 
		 */
		public Loan testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Loan" );

			Loan entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Loan with primary key" );
			msg.append( thePrimaryKey );
			
			LoanFetchOneSummary fetchOneSummary = new LoanFetchOneSummary( thePrimaryKey );

			try {
				entity = LoanService.getLoanInstance().getLoan( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Loan " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Loan.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Loan." );

			StringBuilder msg = new StringBuilder( "Failed to update a Loan : " );        
			Loan entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Loan." );

				// for use later on...
				thePrimaryKey = entity.getLoanId();

				LoanService proxy = LoanService.getLoanInstance();            
				proxy.updateLoan( entity );   

				LOGGER.info( "-- Successfully saved Loan - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Loan.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Loan." );

			try{
			    Loan entity = testRead(); 
				LoanService.getLoanInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Loan with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Loan with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Loans.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Loans:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Loan : " );        
			List<Loan> collection  = null;

			try {
				// call the static get method on the LoanService
				collection = LoanService.getLoanInstance().getAllLoan();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Loan entity = null;            
					Iterator<Loan> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getLoanId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

